function generateAttendance(studentId: string, months = 3): AttendanceRecord[] {
  const records: AttendanceRecord[] = []
  const statuses: AttendanceStatus[] = ['Present', 'Present', 'Present', 'Present', 'Present', 'Present', 'Present', 'Present', 'Late', 'Absent', 'Present', 'Present', 'Leave', 'Present', 'Present']
  let id = 1
  const today = new Date()
  const startDate = new Date(today)
  startDate.setMonth(startDate.getMonth() - months)
  for (let d = new Date(startDate); d <= today; d.setDate(d.getDate() + 1)) {
    const day = d.getDay()
    if (day === 0 || day === 6) continue
    const dayOfMonth = d.getDate()
    const idx = (dayOfMonth + studentId.charCodeAt(1)) % statuses.length
    const status = statuses[idx]
    records.push({
      id: `att-${studentId}-${id++}`,
      studentId,
      date: d.toISOString().split('T')[0],
      status,
      checkInTime: status === 'Present' ? '09:15 AM' : status === 'Late' ? '10:30 AM' : undefined,
    })
  }
  return records
}

